using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "AllCharactersReachedAstreaHeartAchievementDataHiddenHandler", menuName = "Data/Achievements/AllCharactersReachedAstreaHeartAchievementDataHiddenHandler")]
public class AllCharactersReachedAstreaHeartAchievementDataHiddenHandler : AchievementDataHiddenHandler
{
	[SerializeField]
	protected PlayerProgressionData playerProgressionData;

	public override bool IsHidden()
	{
		return !playerProgressionData.AllCharactersReachedAstreaHeart();
	}
}
